svg.script:

(function () {
  var root = document.getElementById('a16p11-svg');
  if (!root) {
    var all = document.getElementsByClassName('a16p11-root');
    root = all && all[0] ? all[0] : null;
  }
  if (!root) return;

  var cases = {
    none: {
      bridge: 'off',
      verdict: 'none',
      kicker: 'SETA',
      main: 'Escolha um caso',
      sub: 'A bipartição já ensina sem clique',
      worlds: []
    },
    low: {
      bridge: 'off',
      verdict: 'closed',
      kicker: 'SETA APAGADA',
      main: 'Fica no rastreio',
      sub: 'US+sangue normais · sem invasivo',
      worlds: ['a16p11-world-screen']
    },
    pos: {
      bridge: 'on',
      verdict: 'open',
      kicker: 'SETA ACESA',
      main: 'Oferecer invasivo',
      sub: 'Rastreio + · consentimento · não forçar',
      worlds: ['a16p11-world-screen', 'a16p11-world-dx']
    },
    high: {
      bridge: 'on',
      verdict: 'open',
      kicker: 'SETA ACESA',
      main: 'Alto risco real',
      sub: 'Começa no não invasivo · decisão dela',
      worlds: ['a16p11-world-screen', 'a16p11-world-dx']
    },
    age35: {
      bridge: 'blocked',
      verdict: 'trap',
      kicker: 'PEGADINHA',
      main: '≥35 sozinha ≠ invasivo',
      sub: 'Idade é clima · associa a rastreio',
      worlds: ['a16p11-world-screen']
    },
    consang: {
      bridge: 'on',
      verdict: 'open',
      kicker: 'SETA ACESA',
      main: 'Perdas / consanguinidade',
      sub: 'Alto risco · reforça invasivo com consentimento',
      worlds: ['a16p11-world-screen', 'a16p11-world-dx']
    }
  };

  var btnIds = [
    'a16p11-btn-low', 'a16p11-btn-pos', 'a16p11-btn-high',
    'a16p11-btn-age35', 'a16p11-btn-consang', 'a16p11-btn-reset'
  ];
  var worldIds = ['a16p11-world-screen', 'a16p11-world-dx'];
  var vKicker = document.getElementById('a16p11-verdict-kicker');
  var vMain = document.getElementById('a16p11-verdict-main');
  var vSub = document.getElementById('a16p11-verdict-sub');
  var caption = document.getElementById('a16p11-bridge-caption');
  var subCap = document.getElementById('a16p11-bridge-sub');
  var tooltip = document.getElementById('a16p11-tooltip');
  var tipBg = document.getElementById('a16p11-tooltip-bg');
  var tipTitle = document.getElementById('a16p11-tooltip-title');
  var tipBody = document.getElementById('a16p11-tooltip-body');

  function clearOn() {
    var on = root.querySelectorAll('.a16p11-on');
    for (var i = 0; i < on.length; i++) on[i].classList.remove('a16p11-on');
    for (var j = 0; j < btnIds.length; j++) {
      var b = document.getElementById(btnIds[j]);
      if (b) b.classList.remove('a16p11-active');
    }
  }

  function setBridgeLabels(bridge) {
    if (!caption || !subCap) return;
    if (bridge === 'on') {
      caption.textContent = 'PASSAGEM ABERTA';
      subCap.textContent = 'oferecer invasivo';
    } else if (bridge === 'blocked') {
      caption.textContent = 'BLOQUEADA';
      subCap.textContent = '≥35 sozinha não basta';
    } else {
      caption.textContent = 'PASSAGEM';
      subCap.textContent = 'só se + / alto risco';
    }
  }

  function setCase(key) {
    var cfg = cases[key] || cases.none;
    clearOn();
    root.setAttribute('data-case', key);
    root.setAttribute('data-bridge', cfg.bridge);
    root.setAttribute('data-verdict', cfg.verdict);
    if (vKicker) vKicker.textContent = cfg.kicker;
    if (vMain) vMain.textContent = cfg.main;
    if (vSub) vSub.textContent = cfg.sub;
    setBridgeLabels(cfg.bridge);
    var n;
    for (n = 0; n < cfg.worlds.length; n++) {
      var w = document.getElementById(cfg.worlds[n]);
      if (w) w.classList.add('a16p11-on');
    }
    if (key === 'none') {
      for (n = 0; n < worldIds.length; n++) {
        var ww = document.getElementById(worldIds[n]);
        if (ww) ww.classList.add('a16p11-on');
      }
    }
    if (key !== 'none') {
      for (var k = 0; k < btnIds.length; k++) {
        var btn = document.getElementById(btnIds[k]);
        if (btn && btn.getAttribute('data-case') === key) btn.classList.add('a16p11-active');
      }
    }
  }

  function bindBtn(id) {
    var el = document.getElementById(id);
    if (!el) return;
    var run = function () {
      setCase(el.getAttribute('data-case') || 'none');
    };
    el.addEventListener('click', run);
    el.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        run();
      }
    });
  }
  for (var i = 0; i < btnIds.length; i++) bindBtn(btnIds[i]);

  function wrapBody(body, maxChars) {
    var words = (body || '').split(/\s+/);
    var lines = [];
    var cur = '';
    for (var w = 0; w < words.length; w++) {
      var next = cur ? cur + ' ' + words[w] : words[w];
      if (next.length > maxChars && cur) {
        lines.push(cur);
        cur = words[w];
      } else {
        cur = next;
      }
    }
    if (cur) lines.push(cur);
    return lines.slice(0, 3);
  }

  function showTip(title, body, clientX, clientY) {
    if (!tooltip || !tipTitle || !tipBody) return;
    tipTitle.textContent = title || '';
    var lines = wrapBody(body, 44);
    tipBody.textContent = lines[0] || '';
    var extra = tooltip.querySelectorAll('.a16p11-tip-extra');
    for (var e = 0; e < extra.length; e++) {
      if (extra[e].parentNode) extra[e].parentNode.removeChild(extra[e]);
    }
    for (var L = 1; L < lines.length; L++) {
      var t = document.createElementNS('http://www.w3.org/2000/svg', 'text');
      t.setAttribute('class', 'a16p11-tooltip-body a16p11-tip-extra');
      t.setAttribute('x', '12');
      t.setAttribute('y', String(42 + L * 15));
      t.textContent = lines[L];
      tooltip.appendChild(t);
    }
    var tw = 300;
    var th = 36 + Math.max(1, lines.length) * 16;
    if (tipBg) {
      tipBg.setAttribute('width', String(tw));
      tipBg.setAttribute('height', String(th));
    }
    tooltip.classList.add('a16p11-show');
    moveTip(clientX, clientY);
  }

  function moveTip(clientX, clientY) {
    if (!tooltip || !tooltip.classList.contains('a16p11-show')) return;
    var ctm = root.getScreenCTM();
    if (!ctm) return;
    var pt = root.createSVGPoint();
    pt.x = clientX;
    pt.y = clientY;
    var sp = pt.matrixTransform(ctm.inverse());
    var x = sp.x + 14;
    var y = sp.y + 14;
    var vb = root.viewBox.baseVal;
    var maxX = (vb && vb.width ? vb.width : 1000) - 312;
    var maxY = (vb && vb.height ? vb.height : 900) - 90;
    if (x > maxX) x = sp.x - 314;
    if (y > maxY) y = sp.y - 90;
    if (x < 8) x = 8;
    if (y < 8) y = 8;
    tooltip.setAttribute('transform', 'translate(' + x + ',' + y + ')');
  }

  function hideTip() {
    if (tooltip) tooltip.classList.remove('a16p11-show');
  }

  var tips = root.querySelectorAll('[data-tip-title]');
  for (var t = 0; t < tips.length; t++) {
    (function (el) {
      el.addEventListener('mouseenter', function (e) {
        showTip(el.getAttribute('data-tip-title'), el.getAttribute('data-tip-body'), e.clientX, e.clientY);
      });
      el.addEventListener('mousemove', function (e) {
        moveTip(e.clientX, e.clientY);
      });
      el.addEventListener('mouseleave', hideTip);
      el.addEventListener('focus', function () {
        var r = el.getBoundingClientRect();
        showTip(el.getAttribute('data-tip-title'), el.getAttribute('data-tip-body'), r.left + r.width / 2, r.top);
      });
      el.addEventListener('blur', hideTip);
    })(tips[t]);
  }

  root.addEventListener('mousemove', function (e) {
    moveTip(e.clientX, e.clientY);
  });

  setCase('none');
})();
